-- Converte o texto dos blocos dos posts gravados antes dos trechos com link.
--
-- ANTES: "text": "uma frase"          (e itens de lista como string)
-- DEPOIS: "text": [{"text": "uma frase"}]
--
-- Os valores foram GERADOS por `scripts/gerar-migracao-de-trechos.cjs`,
-- que aplica a mesma funcao que a leitura ja aplicava em memoria a cada
-- requisicao. Por construcao, o que fica gravado e o que a pagina ja
-- renderizava — a migracao persiste a normalizacao, e nao muda o conteudo.
--
-- Depois dela, as duas portas que toleravam a forma antiga saem: a
-- conversao em `ingest-mapping.js` e a normalizacao em `queries.js`.

-- assinatura-eletronica-no-servico-publico
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"A pergunta chega quase sempre da mesma forma: precisamos de certificado digital para tudo? A resposta curta é não. A resposta útil depende do documento, de quem assina e do risco envolvido."}]},{"type":"heading","text":[{"text":"Os três níveis de assinatura"}]},{"type":"list","items":[[{"text":"Simples: identifica o signatário por login e senha. Serve para comunicação interna de baixo risco, como um memorando entre setores."}],[{"text":"Avançada: usa mecanismos que garantem integridade e autoria com nível de confiança maior, sem certificado ICP-Brasil."}],[{"text":"Qualificada: baseada em certificado ICP-Brasil. É a exigida quando a lei pede equivalência à assinatura de próprio punho."}]]},{"type":"paragraph","text":[{"text":"Na prática, a maior parte do volume diário de uma prefeitura vive nos dois primeiros níveis. Exigir certificado para tudo trava o fluxo e empurra o servidor de volta para o papel."}]},{"type":"heading","text":[{"text":"Como decidir sem virar jurista"}]},{"type":"paragraph","text":[{"text":"O critério que funciona é o efeito do documento. Se ele cria obrigação para terceiros, movimenta recurso público ou vai para fora da organização, suba o nível. Se circula internamente e é rastreável, a assinatura simples com registro de autoria e data resolve."}]},{"type":"quote","text":[{"text":"Assinatura eletrônica não é sobre tecnologia, é sobre prova. O que se está construindo é a capacidade de demonstrar depois quem assinou o quê e quando."}],"cite":"Equipe notPaper"},{"type":"paragraph","text":[{"text":"É por isso que o registro importa tanto quanto a assinatura em si: sem trilha de auditoria, mesmo o certificado mais forte fica difícil de defender."}]}]' WHERE id = 31;

-- como-comecar-a-digitalizacao-de-documentos
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Todo projeto de digitalização começa com a mesma pergunta errada: quantas caixas nós temos? A pergunta certa é qual documento as pessoas procuram todos os dias e não encontram."}]},{"type":"heading","text":[{"text":"Comece pelo documento que dói"}]},{"type":"paragraph","text":[{"text":"Escolha um único tipo de documento com alta frequência de consulta e dono claro. Certidões, contratos vigentes e processos em andamento costumam liderar essa lista. O acervo histórico pode esperar: ele é grande, mas é consultado raramente."}]},{"type":"list","ordered":true,"items":[[{"text":"Mapeie os cinco documentos mais consultados no atendimento."}],[{"text":"Escolha um deles como piloto e defina quem responde por ele."}],[{"text":"Digitalize o que está em uso, não o que está no arquivo morto."}],[{"text":"Só então avance para o próximo tipo de documento."}]]},{"type":"heading","text":[{"text":"Indexação vale mais que resolução"}]},{"type":"paragraph","text":[{"text":"Uma imagem perfeita que ninguém acha é um arquivo perdido com qualidade alta. Antes de escanear, defina quais campos identificam aquele documento: número, ano, interessado, assunto, secretaria. É esse conjunto que transforma imagem em informação recuperável."}]},{"type":"image","src":"/image/blog/como-comecar-a-digitalizacao-de-documentos-fluxo.png","alt":"Fluxo em quatro etapas: preparar, capturar, indexar e validar","caption":"O fluxo mínimo de digitalização: preparar, capturar, indexar e validar antes de liberar para consulta."},{"type":"heading","text":[{"text":"Defina o que acontece com o papel"}]},{"type":"paragraph","text":[{"text":"Digitalizar sem decidir o destino do original é criar dois acervos para manter. Antes do piloto, defina a tabela de temporalidade: o que pode ser descartado, o que precisa ser guardado e por quanto tempo."}]},{"type":"quote","text":[{"text":"Se depois de digitalizar o servidor continua indo até o armário, o projeto não terminou."}]},{"type":"heading","text":[{"text":"Meça uma coisa só"}]},{"type":"paragraph","text":[{"text":"Escolha um indicador antes de começar: tempo médio para localizar um documento. Meça antes, meça depois do piloto. É o número que sustenta o próximo passo do projeto na conversa com a gestão."}]},{"type":"list","items":[[{"text":"Tempo médio de localização de um documento."}],[{"text":"Percentual de consultas atendidas sem ir ao arquivo físico."}],[{"text":"Retrabalho por documento não encontrado."}]]},{"type":"paragraph","text":[{"text":"Com um tipo de documento resolvido, indexação definida e um número na mão, o segundo ciclo do projeto anda sozinho."}]}]' WHERE id = 32;

-- bpmn-na-pratica-para-prefeituras
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"A diferença entre um desenho de processo e um processo automatizável está no detalhe que quase sempre falta: quem decide, com base em quê, e o que acontece quando a resposta é não."}]},{"type":"heading","text":[{"text":"Raias antes de tarefas"}]},{"type":"paragraph","text":[{"text":"Comece definindo os papéis, não as atividades. Em um pedido de alvará típico existem quatro: o requerente, o protocolo, o setor técnico e a autoridade que assina. Cada raia é uma responsabilidade, não uma pessoa."}]},{"type":"heading","text":[{"text":"Todo desvio precisa de saída"}]},{"type":"paragraph","text":[{"text":"Gateways sem caminho de exceção são a causa mais comum de processo parado. Se o técnico pode pedir complementação, esse retorno tem que estar no modelo, com prazo e responsável."}]},{"type":"list","items":[[{"text":"Cada gateway exclusivo tem todas as saídas nomeadas."}],[{"text":"Todo caminho termina em um evento de fim, inclusive o indeferimento."}],[{"text":"Prazos aparecem como eventos de tempo, não como combinado informal."}]]},{"type":"quote","text":[{"text":"Se o modelo não diz o que acontece quando o prazo estoura, o sistema também não vai saber."}]}]' WHERE id = 33;

-- protocolo-digital-e-o-fim-da-fila-no-balcao
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"O balcão de protocolo concentra dois trabalhos diferentes: receber documento e informar andamento. O segundo é o que consome mais tempo da equipe e é justamente o mais fácil de resolver."}]},{"type":"heading","text":[{"text":"Consulta é autoatendimento"}]},{"type":"paragraph","text":[{"text":"Publicar o andamento com número de protocolo e histórico de tramitação elimina a maior parte das ligações e visitas. O servidor deixa de ser buscador de informação e volta a analisar processo."}]},{"type":"list","items":[[{"text":"Número de protocolo gerado na abertura, visível ao interessado."}],[{"text":"Histórico com data, setor e situação de cada etapa."}],[{"text":"Aviso automático quando falta documento."}]]},{"type":"paragraph","text":[{"text":"A fila que sobra no balcão passa a ser só a que realmente precisa de atendimento humano."}]}]' WHERE id = 34;

-- indicadores-que-toda-secretaria-deveria-acompanhar
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Painel de gestão pública costuma sofrer do mesmo problema: mostra volume e esconde tempo. Volume diz o quanto entrou; tempo diz se está saindo."}]},{"type":"heading","text":[{"text":"Os cinco que importam"}]},{"type":"list","ordered":true,"items":[[{"text":"Tempo médio de tramitação por tipo de processo."}],[{"text":"Processos parados há mais de trinta dias."}],[{"text":"Etapa onde o processo passa mais tempo esperando."}],[{"text":"Percentual de devoluções por documentação incompleta."}],[{"text":"Prazos legais vencidos ou a vencer nos próximos sete dias."}]]},{"type":"quote","text":[{"text":"Gargalo não aparece em média. Aparece na fila que está esperando na etapa seguinte."}]},{"type":"paragraph","text":[{"text":"Os dois últimos indicadores são os que mais mudam comportamento, porque transformam risco jurídico em item de agenda semanal."}]}]' WHERE id = 35;

-- lgpd-na-gestao-publica-o-que-muda-no-dia-a-dia
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"No setor público, a base legal para tratar dados normalmente já existe: é a execução de política pública. O que a LGPD cobra de fato é controle de acesso, finalidade e rastro."}]},{"type":"heading","text":[{"text":"Acesso por necessidade, não por hierarquia"}]},{"type":"paragraph","text":[{"text":"O erro mais comum é dar visão total a quem tem cargo alto e visão nenhuma a quem executa. O critério correto é a necessidade da tarefa: quem analisa o processo vê o processo, e o histórico registra que viu."}]},{"type":"list","items":[[{"text":"Perfis de acesso ligados à atividade, não ao organograma."}],[{"text":"Registro de quem consultou dado pessoal sensível."}],[{"text":"Prazo de guarda definido por tipo de documento."}]]},{"type":"quote","text":[{"text":"Se ninguém consegue dizer quem abriu aquele processo na semana passada, o problema não é a LGPD - é a falta de trilha."}]}]' WHERE id = 36;

-- memorando-eletronico-comunicacao-interna-rastreavel
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"A comunicação interna é onde a decisão nasce, mas é também onde o registro costuma morrer. Combinar por mensagem e formalizar depois é a origem da maior parte dos processos sem histórico."}]},{"type":"heading","text":[{"text":"O mínimo que precisa ficar registrado"}]},{"type":"list","items":[[{"text":"Numeração única e sequencial por origem."}],[{"text":"Autor, data de criação e destinatários."}],[{"text":"Confirmação de leitura por destinatário."}],[{"text":"Anexos vinculados ao próprio memorando, não a um e-mail paralelo."}]]},{"type":"paragraph","text":[{"text":"Com esses quatro itens, a comunicação interna deixa de ser conversa e passa a ser documento consultável meses depois."}]}]' WHERE id = 37;

-- ged-ou-pasta-compartilhada-a-diferenca-que-custa-caro
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Pasta compartilhada guarda arquivo. GED guarda documento com contexto. A distinção parece sutil até alguém precisar provar qual versão estava vigente em determinada data."}]},{"type":"heading","text":[{"text":"Onde a pasta quebra"}]},{"type":"list","items":[[{"text":"Versão: contrato_final_v3_revisado.pdf não é controle de versão."}],[{"text":"Permissão: quem tem acesso à pasta tem acesso a tudo dentro dela."}],[{"text":"Rastro: apagar um arquivo não deixa registro de quem apagou."}],[{"text":"Temporalidade: nada expira, nada é descartado, o volume só cresce."}]]},{"type":"quote","text":[{"text":"O custo da pasta compartilhada não aparece no orçamento. Aparece no tempo gasto para provar o que já era verdade."}]}]' WHERE id = 38;

-- workflow-de-aprovacao-como-reduzir-o-tempo-de-tramitacao
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Antes de automatizar, meça onde o processo espera. Na maioria dos fluxos de aprovação, o tempo de análise é minoria: o que consome o prazo é a fila entre etapas."}]},{"type":"heading","text":[{"text":"Reduza etapas antes de automatizar"}]},{"type":"paragraph","text":[{"text":"Aprovação em série com quatro assinaturas para liberar valor baixo é desenho, não exigência. Revise alçadas primeiro; automatizar depois multiplica o ganho em vez de congelar o problema."}]},{"type":"list","ordered":true,"items":[[{"text":"Levante o tempo real de cada etapa, separando análise de espera."}],[{"text":"Reveja alçadas por faixa de valor ou risco."}],[{"text":"Defina prazo e responsável por etapa, com escalonamento automático."}],[{"text":"Só então implemente o fluxo no sistema."}]]},{"type":"quote","text":[{"text":"Automatizar sem revisar alçada é pavimentar o caminho errado."}]}]' WHERE id = 39;

-- certidoes-online-e-a-experiencia-do-cidadao
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"restaurado"}]}]' WHERE id = 40;

-- inteligencia-artificial-em-processos-administrativos
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Conteúdo em elaboração para revisão interna antes da publicação."}]}]' WHERE id = 41;

-- assinatura-digital-no-setor-publico-o-que-muda-quando-ela-fica-dentro-do-processo
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Segundo reportagem publicada pelo portal We News e por publicações oficiais divulgadas em 2025 e 2026, órgãos públicos vêm avançando na tramitação eletrônica e no uso de assinatura em documentos e atos administrativos. O movimento importa menos pelo anúncio em si e mais pelo problema que ele expõe: muita iniciativa de digitalização continua parando justamente na etapa em que alguém precisa assinar."}]},{"type":"heading","text":[{"text":"O processo continua sendo de papel quando a assinatura fica fora dele"}]},{"type":"paragraph","text":[{"text":"Esse é um dos pontos mais comuns de atrito na rotina administrativa. O documento nasce no sistema, passa por setores, recebe ajustes, segue para aprovação e, no fim, sai do fluxo para ser impresso. Depois volta escaneado. Nesse momento, o órgão passa a conviver com duas versões do mesmo documento: a que circulou no processo e a que voltou assinada."}]},{"type":"paragraph","text":[{"text":"O efeito disso não é só operacional. Fica mais difícil saber qual é a versão final, quem já assinou, quem ainda precisa agir e em que ponto o andamento travou. Quando há mais de um participante, o atraso deixa de ser exceção e vira parte do rito."}]},{"type":"paragraph","text":[{"text":"Por isso, a discussão sobre assinatura no setor público não é apenas uma discussão sobre tecnologia de assinatura. É uma discussão sobre desenho de processo."}]},{"type":"heading","text":[{"text":"O problema não está só em assinar, mas em acompanhar"}]},{"type":"paragraph","text":[{"text":"Assinar um documento é uma etapa. Controlar essa etapa é outra. Na prática, muitos fluxos emperram porque ninguém consegue enxergar com clareza o estado da assinatura. O documento foi enviado? Falta quem? Houve recusa? É possível corrigir e reenviar sem recomeçar tudo?"}]},{"type":"paragraph","text":[{"text":"Sem esse acompanhamento, o processo depende de cobrança manual, mensagem paralela e conferência fora do sistema. O gestor deixa de ter visão do fluxo e passa a depender da memória de quem estava conduzindo aquele caso."}]},{"type":"paragraph","text":[{"text":"Isso pesa ainda mais quando a assinatura envolve pessoas de áreas diferentes ou participantes externos ao órgão. Se o caminho para assinar é difícil, o processo volta a procurar atalhos fora do ambiente oficial."}]},{"type":"heading","text":[{"text":"Compatibilidade com a regra não nasce do discurso, e sim do registro do processo"}]},{"type":"paragraph","text":[{"text":"Quando um órgão passa a disciplinar assinatura eletrônica e tramitação digital, o ponto central da rotina não é repetir o texto da norma. É conseguir manter o documento dentro de um fluxo com etapas claras, participantes definidos e histórico verificável."}]},{"type":"paragraph","text":[{"text":"Na prática, é isso que sustenta a operação diária: saber quem participou, quando participou, em qual versão do documento e em que sequência. Sem esse encadeamento, a assinatura vira só o fim de um arquivo. Com esse encadeamento, ela passa a fazer parte do processo administrativo como um todo."}]},{"type":"paragraph","text":[{"text":"É aí que a compatibilidade com a forma de trabalho exigida na administração pública deixa de ser argumento abstrato e aparece no funcionamento concreto da rotina."}]},{"type":"heading","text":[{"text":"O que muda quando a assinatura faz parte do fluxo"}]},{"type":"paragraph","text":[{"text":"No notPaper, a assinatura digital e a assinatura eletrônica acontecem dentro do próprio processo. O documento não precisa sair do fluxo para ser assinado. Na montagem da solicitação, o usuário escolhe quais anexos serão assinados, define os participantes e posiciona visualmente assinatura e rubrica no PDF."}]},{"type":"paragraph","text":[{"text":"O acompanhamento mostra a situação de cada participante, como pendente, assinado ou recusado. Se houver recusa, isso vira um estado do processo, com retorno para reelaboração, em vez de um impasse fora do sistema. Antes do envio, a plataforma também valida se existe anexo selecionado, se há assinante definido e se a posição da assinatura foi informada."}]},{"type":"paragraph","text":[{"text":"Outro ponto importante é que quem assina não precisa ser servidor. O notPaper permite assinante externo por link, sem conta na plataforma, o que ajuda quando o documento depende da participação de fornecedor ou munícipe."}]},{"type":"paragraph","text":[{"text":"Mais do que digitalizar a última etapa, isso mantém o processo inteiro visível, com responsável, data, hora e versão assinada registradas no mesmo ambiente."}]},{"type":"paragraph","text":[{"text":"No fim, a assinatura deixa de ser a etapa que devolve o órgão ao papel e passa a ser parte do caminho normal do processo digital."}]}]' WHERE id = 50;

-- um-app-municipal-util-comeca-no-processo-nao-na-vitrine
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Segundo reportagem publicada em julho de 2026, prefeituras vêm ampliando o uso de aplicativos para concentrar serviços e facilitar a vida do cidadão. O movimento importa porque revela uma pressão antiga da gestão municipal: oferecer uma porta digital de entrada sem criar, por trás dela, mais retrabalho para as equipes."}]},{"type":"heading","text":[{"text":"O problema não é só ter um aplicativo"}]},{"type":"paragraph","text":[{"text":"Quase toda prefeitura já conhece a demanda. O cidadão quer resolver pelo celular o que antes exigia ida ao balcão, papel, cópia de documento e espera por retorno. Mas, na rotina do órgão, isso só funciona de verdade quando a solicitação que nasce no app entra no mesmo processo que a equipe acompanha internamente."}]},{"type":"paragraph","text":[{"text":"Quando o aplicativo vira apenas uma camada de formulário, a dificuldade continua. O pedido chega, alguém precisa repassar para outro setor, o andamento se perde entre mensagens, e a pergunta volta rápido: onde está minha solicitação? O canal digital existe, mas o processo continua fragmentado."}]},{"type":"heading","text":[{"text":"O que costuma travar o atendimento"}]},{"type":"paragraph","text":[{"text":"O gargalo raramente está na abertura do pedido. Está no depois. Um serviço municipal quase nunca depende de uma pessoa só. Ele passa por setor, análise, complemento de documento, aprovação e resposta. Se cada etapa fica em um lugar diferente, a prefeitura ganha volume de entrada, mas não ganha controle."}]},{"type":"paragraph","text":[{"text":"Por isso, app municipal não se sustenta só com tela bonita ou catálogo grande. O que sustenta é a capacidade de encaminhar a demanda para o fluxo correto, registrar autor e data, controlar prazo, guardar anexos e mostrar andamento sem exigir consulta manual da equipe a cada novo protocolo."}]},{"type":"paragraph","text":[{"text":"É esse desenho que separa um canal de atendimento de um simples formulário online."}]},{"type":"heading","text":[{"text":"O que o cidadão precisa encontrar nesse canal"}]},{"type":"paragraph","text":[{"text":"Para o cidadão, a experiência parece simples. Ele quer abrir a solicitação, anexar o que for necessário e acompanhar depois. Mas, para a prefeitura, isso pede estrutura. O serviço precisa estar publicado com requisitos e documentos obrigatórios claros. A manifestação de ouvidoria precisa ter tratamento próprio. O histórico precisa continuar visível do começo ao fim."}]},{"type":"paragraph","text":[{"text":"Sem isso, o município digitaliza a entrada e mantém analógico o resto. O resultado é devolução por falta de documento, encaminhamento errado e acúmulo de resposta manual para explicar o estado de cada demanda."}]},{"type":"heading","text":[{"text":"O que muda quando o app e o processo são o mesmo"}]},{"type":"paragraph","text":[{"text":"No notPaper, o aplicativo Sua Cidade pode ser habilitado para que o cidadão abra e acompanhe solicitações pelo celular em serviços da Carta de Serviços e na Ouvidoria. Essa abertura não gera um pedido solto: ela entra no mesmo processo que tramita dentro da prefeitura."}]},{"type":"paragraph","text":[{"text":"Na prática, isso significa que o município pode publicar serviços com requisitos e documentos obrigatórios parametrizados, receber manifestações de ouvidoria com tratamento de sigilo e anonimato, acompanhar protocolos com histórico e andamento em tempo real e manter a tramitação interna com responsável definido, prazo e trilha de auditoria."}]},{"type":"paragraph","text":[{"text":"Além da abertura de solicitações, o app pode reunir notificações, avaliação da gestão pública, feriados e datas, comunicação social do município e marketplace de comércio local, conforme a configuração de cada cidade. O ponto central, porém, não é a quantidade de telas. É o fato de o atendimento ao cidadão e a tramitação interna fazerem parte do mesmo fluxo."}]},{"type":"heading","text":[{"text":"O ganho real para a prefeitura"}]},{"type":"paragraph","text":[{"text":"Quando esse desenho existe, o aplicativo deixa de ser só um canal de entrada. Ele passa a organizar a relação entre cidadão e prefeitura. A equipe recebe a demanda já dentro do processo certo. O cidadão acompanha sem depender de ligação ou balcão. E a administração ganha menos repasse manual e mais clareza sobre onde cada solicitação está."}]},{"type":"paragraph","text":[{"text":"No fim, o app municipal mais útil não é o que apenas concentra serviços. É o que transforma cada pedido aberto pelo cidadão em processo acompanhado de verdade."}]}]' WHERE id = 51;

-- alvara-organizado-anda-mais-rapido-quando-o-processo-nao-se-perde-entre-setores
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Segundo publicações oficiais divulgadas em agosto de 2026 e reportagem publicada em agosto de 2026, prefeituras vêm concentrando pedidos de alvará e habite-se em protocolo digital e reorganizando a tramitação desses processos. O movimento chama atenção menos pela troca do papel pela tela e mais pelo problema que ele expõe: alvará costuma atrasar quando a prefeitura não consegue manter o processo visível, íntegro e andando na ordem certa."}]},{"type":"heading","text":[{"text":"O gargalo raramente está em uma etapa só"}]},{"type":"paragraph","text":[{"text":"Quando o licenciamento urbano depende de mais de um setor, o atraso quase nunca nasce de um único parecer. Ele aparece na passagem entre áreas, na devolução mal registrada, no comprovante que chega por fora, no projeto que fica parado à espera de conferência e na dificuldade de saber quem precisa agir agora."}]},{"type":"paragraph","text":[{"text":"Na rotina, isso significa retrabalho. O mesmo dado é conferido mais de uma vez. O mesmo documento precisa ser procurado em lugares diferentes. E o requerente, sem enxergar o que aconteceu, volta ao balcão ou liga para perguntar em que ponto o pedido parou."}]},{"type":"paragraph","text":[{"text":"O problema, portanto, não é só lentidão. É desorganização de fluxo. Quando cada etapa depende de memória, planilha paralela ou mensagem solta, o processo até anda, mas anda sem previsibilidade."}]},{"type":"heading","text":[{"text":"Centralizar não basta se o fluxo continuar confuso"}]},{"type":"paragraph","text":[{"text":"Muitos órgãos já perceberam que espalhar pedidos em canais diferentes piora tudo. Centralizar a entrada ajuda, mas não resolve sozinha. Se o processo entra por um lugar único e depois se fragmenta internamente, a prefeitura continua com a mesma dificuldade: saber o que foi analisado, o que voltou para correção e o que ainda depende de outro setor."}]},{"type":"paragraph","text":[{"text":"É por isso que a melhora real não vem apenas de receber documentos por meio digital. Ela vem de transformar o caminho do processo em algo explícito. Cada etapa precisa ter responsável, exigência definida e registro do que aconteceu ali."}]},{"type":"paragraph","text":[{"text":"Sem isso, a tela só substitui a pasta. O descontrole continua, agora com aparência digital."}]},{"type":"heading","text":[{"text":"O que costuma falhar na fase final"}]},{"type":"paragraph","text":[{"text":"Há um ponto especialmente sensível nesses processos: a etapa de liberação. É nela que costumam se concentrar a emissão do documento, a conferência final e as obrigações que surgem como consequência do licenciamento."}]},{"type":"paragraph","text":[{"text":"Quando essa fase depende de ações manuais separadas, o risco aumenta. Um documento pode ser emitido sem que o processo tenha passado por todas as validações. Um dado pode ser redigitado com erro. Uma falha pode desaparecer porque não existe fila própria para tratá-la depois."}]},{"type":"paragraph","text":[{"text":"Na prática, isso afeta duas coisas que a administração municipal precisa proteger ao mesmo tempo: velocidade e segurança. Se acelera sem organização, cresce o risco de erro. Se tenta revisar tudo no fim, o processo trava."}]},{"type":"heading","text":[{"text":"O que muda quando o processo é desenhado"}]},{"type":"paragraph","text":[{"text":"No CADOB da notPaper, o licenciamento de obras é conduzido como fluxo, não como coleção de tarefas soltas. O pedido passa por etapas definidas, pode voltar para adequação sem perder protocolo nem histórico, reúne pareceres no mesmo processo e segue até a liberação com registro do que foi feito em cada fase."}]},{"type":"paragraph","text":[{"text":"Na etapa final, o documento pode ser gerado a partir de modelo e carimbado no próprio PDF. E o envio ao SISOBRAPREF é disparado na liberação do alvará, a partir dos dados que já estão no processo. Se houver falha, ela não some no caminho: cai em uma fila própria, com relatório, para reprocessamento."}]},{"type":"paragraph","text":[{"text":"O ganho mais importante está aí. Um processo mais organizado tende a andar mais rápido porque reduz redigitação, volta desnecessária e perda de contexto. E tende a ser mais seguro porque cada passagem fica registrada, cada etapa tem dono e a falha vira trabalho visível, não pendência esquecida."}]},{"type":"paragraph","text":[{"text":"Digitalizar é importante. Mas, no licenciamento, o que realmente muda o resultado é sair do improviso e colocar o processo inteiro em ordem."}]}]' WHERE id = 52;

-- quando-a-assinatura-sai-do-papel-o-processo-anda-de-verdade
UPDATE posts SET content = N'[{"type":"paragraph","text":[{"text":"Segundo publicação do setor divulgada em agosto de 2026, a digitalização de documentos continua esbarrando no mesmo ponto: o processo até circula entre setores em meio eletrônico, mas volta ao papel na etapa de assinatura. É aí que a agilidade prometida se perde. O documento sai do fluxo, alguém imprime, outra pessoa assina, depois alguém digitaliza de novo. No fim, o que parecia resolvido volta a depender de deslocamento, espera e retrabalho."}]},{"type":"heading","text":[{"text":"O gargalo não está no início do processo"}]},{"type":"paragraph","text":[{"text":"Na rotina de uma prefeitura, o problema raramente começa na abertura do pedido. Muitas vezes o protocolo já existe, os documentos já foram anexados e a análise já passou por mais de um setor. O atraso aparece no fim, quando falta a assinatura de quem aprova, de quem valida ou de quem precisa apenas acompanhar."}]},{"type":"paragraph","text":[{"text":"Esse detalhe muda o processo inteiro. Enquanto a assinatura fica fora do fluxo, ninguém consegue enxergar com clareza quem já concluiu a própria parte e quem está segurando o documento. O resultado é cobrança por telefone, envio repetido de arquivo por e-mail e dúvida sobre qual versão é a certa."}]},{"type":"paragraph","text":[{"text":"É por isso que a assinatura pesa tanto na eficiência administrativa. Não é só uma formalidade no final. Ela define se o processo termina de forma organizada ou se volta a depender de etapas manuais."}]},{"type":"heading","text":[{"text":"Agilidade não vem de correr mais, vem de eliminar a volta ao papel"}]},{"type":"paragraph","text":[{"text":"Quando um documento precisa circular entre várias pessoas para ser assinado, o maior desperdício não é o ato de assinar. É tudo o que se cria em volta dele. Impressão, envio, conferência, reenvio, digitalização e checagem de versão consomem tempo da equipe e quebram a continuidade do trabalho."}]},{"type":"paragraph","text":[{"text":"Por isso, falar em agilidade nesse contexto não é falar de pressa. É falar de reduzir mudança de meio. Se o documento nasce no sistema, tramita no sistema e é assinado no mesmo ambiente, o processo não precisa sair da trilha para terminar."}]},{"type":"paragraph","text":[{"text":"Na prática, isso também melhora a previsibilidade. Em vez de depender da memória de quem enviou ou recebeu, a equipe acompanha a situação do documento no próprio processo. Fica mais simples saber se ele está pendente, assinado ou recusado, e agir sem abrir uma sequência paralela de mensagens."}]},{"type":"heading","text":[{"text":"Segurança, nesse caso, é controle do caminho"}]},{"type":"paragraph","text":[{"text":"Em processos administrativos, segurança não é só proteger o arquivo final. É conseguir saber quem participou, em que momento participou e sobre qual versão do documento aquela ação aconteceu."}]},{"type":"paragraph","text":[{"text":"Quando a assinatura acontece fora do fluxo, esse controle enfraquece. O órgão passa a conviver com cópias em lugares diferentes, dúvidas sobre o arquivo mais recente e pouca visibilidade sobre o percurso do documento. Isso aumenta o risco operacional e torna a conferência mais trabalhosa."}]},{"type":"paragraph","text":[{"text":"Já quando a assinatura faz parte do processo, o caminho fica mais claro. O acompanhamento deixa de depender de conversas soltas e passa a ficar vinculado ao próprio documento. Para quem administra rotinas com mais de um setor, isso reduz incerteza e evita que a tramitação se desorganize justamente na etapa final."}]},{"type":"heading","text":[{"text":"O que muda quando a assinatura entra no fluxo"}]},{"type":"paragraph","text":[{"text":"Na Notpaper, a assinatura digital e eletrônica é tratada como etapa do fluxo. O documento não precisa sair do processo para ser assinado. Na montagem da solicitação, o usuário escolhe quais anexos vão para assinatura, define os participantes e posiciona visualmente a assinatura e a rubrica no PDF."}]},{"type":"paragraph","text":[{"text":"O processo também distingue papéis diferentes: signatário, aprovador e observador. Isso ajuda a refletir a rotina administrativa como ela é, sem obrigar todo participante a agir da mesma forma. Durante o acompanhamento, fica visível quem está pendente, quem já assinou e quem recusou."}]},{"type":"paragraph","text":[{"text":"Há ainda validações antes do envio. Se faltar anexo, assinante ou posicionamento da assinatura no documento, a transição é bloqueada. O erro deixa de ser descoberto dias depois, quando o arquivo não voltou."}]},{"type":"paragraph","text":[{"text":"Outro ponto importante é a possibilidade de assinatura por participante externo, por link, sem conta na plataforma. Em situações em que quem precisa assinar não faz parte da estrutura interna do órgão, o processo continua no mesmo fluxo, sem criar uma operação paralela."}]},{"type":"paragraph","text":[{"text":"No fim, a agilidade vem da continuidade, a eficiência vem da redução do retrabalho e a segurança vem da clareza sobre quem fez o quê. Quando a assinatura deixa de ser uma etapa solta e passa a fazer parte do processo, o digital finalmente vai até o fim."}]}]' WHERE id = 53;
